const items = $input.all();

const allowedIntents = [
  "ORDER_ISSUE",
  "REFUND_REQUEST",
  "SHIPPING_QUESTION",
  "PRODUCT_QUESTION",
  "GENERAL_QUESTION",
  "OTHER"
];

const intentRequiringOrderID = [
  "ORDER_ISSUE",
  "REFUND_REQUEST",
  "SHIPPING_QUESTION"
];

const allowedCategories = [
  "MISSING_ORDER",
  "WRONG_ITEM",
  "DAMAGED_ITEM",
  "LATE_DELIVERY",
  "REFUND",
  "PRODUCT_INFORMATION",
  "OTHER"
];

const allowedPriorities = [
  "LOW",
  "MEDIUM",
  "HIGH"
];

const allowedSentiments = [
  "POSITIVE",
  "NEUTRAL",
  "FRUSTRATED",
  "ANGRY"
];

return items.map(item => {
  const aiOutput = item.json.output;
  const errors = [];

  if (!allowedIntents.includes(aiOutput.intent)) {
    errors.push("Invalid intent");
  }

  if (!allowedCategories.includes(aiOutput.category)) {
    errors.push("Invalid category");
  }

  if (!allowedPriorities.includes(aiOutput.priority)) {
    errors.push("Invalid priority");
  }

  if (!allowedSentiments.includes(aiOutput.sentiment)) {
    errors.push("Invalid sentiment");
  }

  if (aiOutput.order_id === null || aiOutput.order_id === undefined) {
    if (intentRequiringOrderID.includes(aiOutput.intent)) {
      errors.push("Order ID required for this intent.");
    }
  } else if (
    typeof aiOutput.order_id !== "string" ||
    aiOutput.order_id.trim() === ""
  ) {
    errors.push("Invalid order_id");
  }

  if (
    typeof aiOutput.summary !== "string" ||
    aiOutput.summary.trim() === ""
  ) {
    errors.push("Missing summary");
  }

  return {
    json: {
      valid: errors.length === 0,
      errors,
      ...aiOutput
    }
  };
});

const emails = $('Get email').all();

return emails.map(email => ({
  json: {
    message_id: email.json.messageId ?? "",
    thread_id: email.json.threadId ?? "",
    sender: email.json.from?.value?.[0]?.address ?? "",
    sender_name: email.json.from?.value?.[0]?.name ?? "",
    recipient: email.json.to?.value?.[0]?.address ?? "",
    subject: email.json.subject ?? "",
    body: email.json.text ?? "",
    html_body: email.json.html ?? "",
    received_at: email.json.date ?? ""
  }
}));

