const items = $input.all();

return items.map(item => {
  const ai = item.json;

  return {
    json: {
      escalation_required: true,
      intent: ai.intent,
      priority: ai.priority,
      order_id: ai.order_id,
      summary: ai.summary,
      message: `Customer support escalation required for: ${ai.intent
        .replaceAll("_", " ")
        .toLowerCase()}.`
    }
  };
});

const items = $input.all();

return items.map(item => {
  const thread = item.json;
  const messages = thread.messages ?? [];

  const thread_context = messages
    .map((message, index) => {
      return `Message ${index + 1}
From: ${message.From ?? ""}
Subject: ${message.Subject ?? ""}
Content: ${message.snippet ?? ""}`;
    })
    .join("\n\n");

  return {
    json: {
      ...thread,
      thread_context
    }
  };
});

const ai = $json;

return [
  {
    json: {
      status: "AI_VALIDATION_FAILED",
      errors: ai.errors,
      intent: ai.intent ?? null,
      category: ai.category ?? null,
      priority: ai.priority ?? null,
      sentiment: ai.sentiment ?? null,
      order_id: ai.order_id ?? null,
      summary: ai.summary ?? null,
      message: "AI output failed validation and was not processed."
    }
  }
];
